imgbrowse_open_copy: "Ver el interior de la copia",
localimage_explain: "Abre la imagen como una unidad normal en este equipo, de modo que puedas añadir, sustituir y eliminar archivos dentro de ella —parches, por ejemplo— con el Finder o el Explorador, igual que con una memoria USB. Los cambios se guardan directamente en el archivo de imagen. ps5upload nunca escribe en la imagen; lo hace tu sistema operativo. Expúlsala aquí cuando termines.",
