"pkglib.installAll.what": "¿Qué es «Instalar todo»?",
"pkglib.installAll.whatBody": "«Instalar todo» ejecuta en orden todos los paquetes listos: juego base → actualizaciones → DLC. Si tienes dos actualizaciones de la misma versión (o dos DLC que entran en conflicto), usa la casilla de cada fila para elegir cuál debe instalar esta consola: solo una por grupo. Desmárcala para omitir ese grupo. El botón Instalar de una fila concreta instala siempre solo ese paquete.",
