"connection_prior_killed": "El ayudante anterior no se cerró correctamente",
"connection_prior_killed_detail": "Puede significar que otro payload de la consola lo cerró, que el sistema se quedó sin memoria o que falló. El stderr.log de un informe de errores indica cuál. Si cargas ps5upload con un autoloader, prueba a enviarlo desde aquí.",
