captures_title: "Capturas",
"arcpkg.choose": "Elegir archivo comprimido…",
"arcpkg.help": "Para un .zip, .7z o .rar que contiene uno o más archivos .pkg, en cualquier carpeta. Solo se descomprimen los paquetes, directamente en la PS5 (no se extrae nada en este ordenador), y luego se instalan uno a uno: el juego base antes de su actualización, después el DLC. Un RAR en varias partes (.part1.rar, .part2.rar…) funciona: elige la primera parte y deja las demás junto a ella. Se pide la contraseña cuando un RAR la necesita; los ZIP y 7z protegidos con contraseña no son compatibles.",
"arcpkg.helpNoRar": "Para un .zip o .7z con uno o más archivos .pkg, en cualquier carpeta. Solo se descomprimen los paquetes, directamente en la PS5 (nada se extrae en este dispositivo), y se instalan uno a uno: el juego base antes de su actualización y luego los DLC. Los archivos con contraseña no son compatibles, y .rar necesita la app de escritorio.",
