"install.library.title": "Copias de paquetes en la PS5",
"install.stream.file.help": "Elige un .pkg o .fpkg, o suelta uno en cualquier parte de esta ventana. Mantén la app abierta hasta que termine la instalación; el progreso se ve en la cola de arriba y en Tareas.",
"install.stream.file.title": "Instalar un archivo de paquete",
"install.tab.stream.lead": "La PS5 instala directamente desde este ordenador o desde un enlace. No se pone antes ninguna copia en la PS5, así que no necesita espacio libre allí, y es la forma más fiable de instalar.",
"install.tab.upload.lead": "El paquete se copia primero a la PS5 y luego se instala desde esa copia. Úsalo cuando la PS5 no pueda llegar a este ordenador (Transmitir falla con un error de red), o para conservar paquetes en la PS5 y reinstalarlos más tarde sin este ordenador.",
"install.upload.file.browser": "Copiar un paquete a la PS5 desde aquí requiere la app de escritorio. En la interfaz web, usa Transmitir e instalar, o instala abajo los paquetes que ya están en la PS5.",
"install.upload.file.help": "Elige un .pkg o .fpkg. La copia necesita espacio libre en la PS5 para todo el paquete y se queda en la lista de abajo hasta que la quites.",
"install.upload.file.title": "Copiar un paquete a la PS5 e instalarlo",
"linkcard.confirm.direct": "La PS5 descarga el paquete del enlace por sí misma y lo instala. Este ordenador no hace falta una vez iniciado, y el progreso se ve en la PS5 (Descargas), no aquí. Si la PS5 no puede obtener el enlace, la app lo transmite a través de este ordenador. Reinstalar sobre un juego instalado puede eliminarlo si el instalador de Sony falla. Usa solo enlaces de paquetes en los que confíes y que tengas permiso para instalar.",
"linkcard.confirm.download": "Este ordenador guarda primero todo el paquete en su disco y luego lo instala en la PS5. Debe seguir despierto hasta que ambas cosas terminen y necesita espacio libre para el paquete. Reinstalar sobre un juego instalado puede eliminarlo si el instalador de Sony falla. Usa solo enlaces de paquetes en los que confíes y que tengas permiso para instalar.",
"linkcard.confirm.stream": "Este ordenador descarga el paquete y lo pasa directamente a la PS5, así que debe seguir despierto y conectado hasta que termine la instalación. No se guarda nada en el disco. Reinstalar sobre un juego instalado puede eliminarlo si el instalador de Sony falla. Usa solo enlaces de paquetes en los que confíes y que tengas permiso para instalar.",
"linkcard.confirm.title": "¿Instalar desde este enlace?",
"linkcard.fact.awake": "Mantén este ordenador despierto",
"linkcard.fact.can_close": "Puedes cerrar la app",
