"linkcard.insecure_hint": "Para tu propio servidor o un sitio con el certificado caducado. Se aplica aquí porque este ordenador hace la conexión.",
"linkcard.install": "Instalar desde el enlace",
"linkcard.mode.direct": "La PS5 lo descarga",
"linkcard.mode.direct_body": "La PS5 obtiene el enlace por sí misma. Debe poder llegar al enlace y la dirección debe ser corta (la app acorta una larga y entonces tiene que seguir abierta).",
"linkcard.mode.download": "Descargar aquí primero y luego instalar",
"linkcard.mode.download_body": "Este ordenador guarda todo el paquete y luego lo instala. Es lo más lento, pero un enlace que caduca o se corta a medias solo cuesta reintentar la descarga.",
"linkcard.mode.stream": "Transmitir a través de este ordenador",
