"speedtest.verdict.hundred": "Parece un enlace de 100 Mbit, que tiene su tope cerca de 11 MB/s. Revisa el cable (usa Cat5e o superior) y que todos los puertos de switch o router del camino sean gigabit.",
"speedtest.verdict.mid": "Bien, pero por debajo de lo que da un cable gigabit (90–115 MB/s). Causas habituales: Wi-Fi en alguno de los dos lados u otro tráfico en la red.",
