trace_title: "Medir cómo juega",
trace_measuring: "Midiendo",
trace_what: "Para una imagen de juego LZ4 que cargue como el juego juega. Una versión de medición de ampr_emu registra cada archivo que el juego lee mientras juegas; un perfil creado con esas sesiones elige tamaños de bloque, disposición y cachés por archivo en vez de una sola suposición. Convert lo usa al hacer una imagen LZ4 de este juego.",
