fs_send_dial_hint: "Déjalo vacío para marcar la dirección propia de la consola. Con ps5-tailscale, crea un reenvío local en la consola emisora (su página de estado: 127.0.0.1:19120 → la otra consola:9120) y escribe aquí 127.0.0.1:19120. Quién puede enviar lo deciden las claves de las consolas y un ticket de un solo uso, no la dirección.",
