"fpkg.image.packs_lz4_needs_exfat": "Los paquetes de recursos LZ4 necesitan una imagen .exfat. Los paquetes zstd funcionan con esta.",
"fpkg.image.packs_shadowmount_only": "Un juego empaquetado solo funciona si ShadowMount+ lo monta. El montaje propio de PS5Upload no puede leer los paquetes. Las imágenes normales funcionan de las dos formas.",
"fpkg.image.done_packs": "Monta esta imagen con ShadowMount+: el montaje propio de PS5Upload no puede leer sus paquetes de recursos.",
