"minion_lan_hint": "Desactivado: solo el navegador de la propia PS5 lo abre. Activado: un teléfono, tableta u ordenador de la misma red también puede abrirlo, así que cualquiera en esa red puede. Actívalo solo en casa.",
"minion_open_here": "Abrir aquí",
"minion_remove_note": "Quitar desactiva Minion y borra lo que guarda en la PS5: sus favoritos de Archivos y carpetas recientes, su lista guardada de juegos y su registro del mando. Las carpetas de red, los trucos y las copias de seguridad se conservan; la app del PC también los usa.",
