"fs_drag_hint_move": "Arrastra archivos y carpetas fuera de la ventana para copiarlos a este ordenador, o arrástralos dentro para copiarlos aquí. Mantén pulsada Alt (⌥ Option en un Mac) mientras arrastras para moverlos a una carpeta de aquí.",
"fs_drag_hint": "Arrastra archivos y carpetas fuera de la ventana para copiarlos a este ordenador, o arrástralos dentro para copiarlos aquí.",
