"ps4move_experimental": "Experimental: poner partidas en formato PS4 en una PS5 no siempre funciona, y un juego puede no cargarlas. Prueba primero con un juego; su partida de PS5 se conserva y puedes recuperarla desde las copias del juego.",
"ps4move_safety": "La PS4 solo se lee, nunca se cambia. Sus partidas se copian primero a este ordenador. En la PS5 solo se tocan los juegos que elijas, la partida de cada uno se respalda antes de reemplazarla, y nada más (usuarios, archivos del sistema, trofeos) cambia.",
