"fpkg.ps4_game_note_v2": "Un juego de PS4. Se convierte en un paquete de PS4, una imagen de juego o una carpeta; una imagen o carpeta recibe el param.json que necesita ShadowMount+.",
"fpkg.ps4_merged_note_v2": "El juego de PS4 {title} con su actualización integrada: {from} pasa a ser {to}. Se convierte en un paquete de PS4, una imagen de juego o una carpeta en esa versión.",
"fpkg.ps4_patch_note_v2": "Una actualización de PS4, versión {version}, para {title}. Solo contiene los archivos que cambiaron, así que por sí sola no es un juego: elige abajo el juego al que pertenece, y lo que crees será el juego en esta versión.",
"fpkg.ps4_pkg.options": "Un paquete de PS4 conserva los archivos del juego tal como están: no se comprime nada, el juego conserva todos sus idiomas y cada archivo se vuelve a leer y se compara antes de conservar el paquete.",
"fpkg.ps4_licence_note": "Un complemento de PS4 para {title} que solo es una licencia: desbloquea algo en el juego y no contiene archivos, así que no hay nada que convertir.",
"fpkg.ps4_addon_note": "Un complemento de PS4 para {title}. Sus archivos se convierten en una carpeta, no en una imagen ni en un paquete. ShadowMount+ no monta complementos: llegan al juego solo donde el propio juego los busca, como una carpeta dentro del juego.",
"fpkg.merge.title_patch": "Integrar en el juego",
