"fpkg.merge.pick_game": "Elige el juego de PS4 al que pertenece esta actualización",
"fpkg.merge.pick_update": "Elige una actualización de PS4 para este juego",
"fpkg.image.zstd": "Paquetes de recursos zstd (los más pequeños, para ShadowMount+)",
"fpkg.image.zstd_body": "Empaqueta todo salvo los archivos de sistema del juego en paquetes zstd, escritos directamente en la imagen sin copia temporal. La imagen recibe ampr-emu-ng de quer3q como emulador, comprobado con un resumen publicado antes de usarlo. Un juego ya en paquetes LZ4 se convierte. Desactiva update_emulators en ShadowMount+, o puede cambiar el emulador por uno que no los lea.",
"fpkg.image.zstd_level": "Nivel de compresión",
"fpkg.image.zstd_runtime": "Runtime de los paquetes",
"fpkg.image.zstd_runtime_latest": "Versión más reciente (predeterminada)",
"fpkg.image.zstd_runtime_pinned": "Probada {version}",
"fpkg.image.zstd_runtime_body": "«Más reciente» usa la última versión de ampr-emu-ng en GitHub solo si coincide con el SHA-256 que GitHub publica para ella; si no, o sin conexión, se usa la probada {version}. «Probada» usa siempre {version}.",
"fpkg.folder.zstd_body": "Escribe el juego como una carpeta normal con todo salvo sus archivos de sistema en paquetes zstd, y ampr-emu-ng de quer3q como fakelib/libSceAmpr.sprx. También puede partir de una carpeta de juego. Aquí no se ofrecen paquetes LZ4: solo van en una imagen .exfat. Desactiva update_emulators en ShadowMount+, o puede cambiar el emulador por uno que no los lea.",
"ampr_emu_add_hint": "Este juego lee sus archivos mediante AMPR y no tiene emulador. Algunos juegos así no arrancan desde una imagen sin él, y otros funcionan bien. Añade ampr_emu 0.4.2.1 de drakmor, descargado una vez y comprobado con un resumen conocido. La imagen no cambia: el emulador va en una carpeta backport de ShadowMount+.",
"ampr_emu_done_backport": "Añadido como backport de ShadowMount+ en {folder}. La imagen no cambia. Inicia el juego para probarlo.",
"ampr_emu_done_folder": "Añadido a la carpeta del juego, {folder}. Inicia el juego para probarlo.",
"fpkg.fake_sign_note": "{count} ejecutables simples (sin firmar) de este juego reciben una firma falsa al convertirlo, o no arrancaría. El origen no cambia.",
"fpkg.image.ampr_emu": "Añadir el emulador AMPR",
"fpkg.image.ampr_emu_body": "Este juego lee sus archivos mediante AMPR y no tiene emulador. Algunos juegos así no arrancan desde una imagen sin él, y otros funcionan bien. Añade ampr_emu 0.4.2.1 de drakmor como fakelib/libSceAmpr.sprx, descargado una vez de su versión en GitHub y comprobado con un resumen conocido.",
"fpkg.image.lz4_placement_note": "Guarda una imagen empaquetada en el almacenamiento interno de la consola: se ha informado de una que se quedó en pantalla negra desde USB. Desactiva update_emulators en ShadowMount+, o puede cambiar el emulador por uno que no lee paquetes.",
"smp_rescan": "Buscar ahora",
"smp_rescan_done": "ShadowMount+ está buscando. Detecta imágenes nuevas y vuelve a intentar los juegos que no se montaron.",
