"rp_err_in_use": "Otro dispositivo está usando Remote Play en esta PS5, o la PS5 aún está terminando una sesión. Cierra Remote Play en ese dispositivo (la app PS Remote Play, chiaki) y pulsa Iniciar.",
"rp_err_console_ended": "La PS5 terminó la transmisión: {reason}",
"rp_err_no_session": "La transmisión terminó mientras esta página no estaba. Pulsa Iniciar para volver a jugar.",
"rp_err_other": "La transmisión se detuvo.",
"rp_err_lost": "La conexión con la PS5 se cortó durante la transmisión. Vuelve a iniciarla; si sigue pasando, conecta la PS5 o este dispositivo por cable.",
"rp_err_rp_off": "Remote Play está desactivado en la PS5. En la consola, abre Ajustes › Sistema › Juego remoto y activa Habilitar Juego remoto (si ya aparece activado, desactívalo y vuelve a activarlo); luego pulsa Iniciar. ¿Aparece en gris? La cuenta del usuario de la PS5 debe estar activada, y una PS5 cambiada al entorno NP sp-int lo mantiene desactivado: vuelve a ponerla en np.",
"rp_err_refused": "La PS5 rechazó iniciar Remote Play. En la consola, revisa Ajustes › Sistema › Juego remoto › Habilitar Juego remoto (desactívalo y actívalo), pulsa Permitir en Jugar › Configurar o vuelve a vincular. El código de abajo indica qué rechazo fue. ¿Sigue rechazando? Reinicia la PS5: una consola encendida mucho tiempo puede rechazar hasta reiniciarse.",
"web_update_how_docker": "Para actualizar, ejecuta esto en la carpeta de tu archivo compose (Watchtower también puede hacerlo por ti):",
"web_update_how_app": "Esta página viene de PS5Upload en otro ordenador. Actualiza la app allí y esta página se actualizará con ella.",
"rp_err_unreachable": "La PS5 no responde en la red. Comprueba que está encendida, en la misma red y que Remote Play está activado en sus ajustes.",
"rp_err_video": "La PS5 rechazó ese tamaño de imagen. Prueba 720p.",
"rp_err_no_session_id": "La PS5 aceptó la transmisión pero no terminó de iniciarla. Mira la TV por si la PS5 está preguntando algo. Un juego iniciado por otro usuario de la PS5 también puede retenerla: cambia a tu usuario o cierra ese juego y pulsa Iniciar.",
"rp_err_wake": "La PS5 está en modo de reposo y no se despertó. Comprueba que está enchufada y que en Ajustes › Sistema › Ahorro de energía › Funciones disponibles en el modo de reposo están activados «Permanecer conectado a Internet» y «Permitir encender la PS5 desde la red».",
