"rp_picture_here": "Imagen en este dispositivo",
"rp_picture_here_hint": "Desactivado, las nuevas transmisiones empiezan aquí sin imagen, sonido ni mando, lo que ahorra CPU y batería de este dispositivo. Los amigos en Play Together y Go live siguen recibiendo la transmisión, y puedes activarlo desde ella cuando quieras.",
"rp_picture_off_title": "La imagen está desactivada en este dispositivo",
"rp_picture_off_body": "La transmisión sigue para tus amigos y tu emisión. Aquí tampoco hay sonido ni mando, así que este dispositivo apenas tiene trabajo.",
"rp_picture_turn_on": "Activar la imagen",
"rp_picture_turn_off": "Desactivar la imagen en este dispositivo",
"golive_picture_hint": "Desactivado, este ordenador reenvía la transmisión sin decodificarla ni mostrarla, lo que ahorra CPU y calor. Deja la app abierta; el control sigue aquí.",
"pt_picture_hint": "Desactivado, este dispositivo solo invita a tus amigos: sin imagen, sonido ni mando aquí, y su partida continúa. Para jugar en la tele.",
"pt_tv_title": "¿Juegas en la tele?",
"pt_tv_note": "Esta transmisión tiene la sesión iniciada con el usuario de PS5 que emparejaste con PS5Upload. Pulsa PS en el DualSense de la consola y elige otro usuario: ese eres tú en la tele. Si eliges el usuario de la transmisión, esta termina para todos, amigos incluidos. Algunos juegos también cuentan al usuario de la transmisión como jugador, lo que puede dejar un sitio menos para un amigo.",
"pt_tv_seats": "Una PS5 admite 4 mandos. Con tu DualSense en la tele, el primer amigo usa el mando del propio stream y juega como su usuario, sin elegir usuario, y otros 2 reciben su propio mando: hay sitio para 3 amigos.",
"pt_stream_seat_note": "Un amigo está usando el mando de este stream, así que tu mando aquí no juega hasta que se vaya.",
