"activity_waiting_count": "{count} en espera",
"send_title_v2": "Subir e instalar",
"collection.send_many_body_v2": "Cada PS5 recibe lo que le falta: el paquete del juego, o su carpeta, imagen o archivo comprimido, además de actualizaciones más recientes y DLC para los juegos que tiene. Los paquetes se transmiten desde este ordenador; el resto se sube a la unidad elegida en «Subir e instalar», en la carpeta homebrew.",
"first_run_step4_body_v3": "Conecta a tu PS5 una memoria USB con imágenes de juego .ffpkg y ShadowMount+ las montará automáticamente — aparecerán en Juegos. Para enviar otros archivos o instalar paquetes .pkg, usa «Subir e instalar».",
"first_run_go_upload_v2": "Abrir «Subir e instalar»",
"fpkg.aboutFake_v2": "El resultado es un paquete falso, así que la consola necesita tener cargado el soporte de paquetes falsos antes de instalarlo: kstuff (la versión con soporte de paquetes falsos de PS5), a53_ppr_install_fast.elf y shadowmountplus.elf, en ese orden. «Subir e instalar» dice lo mismo junto a sus botones de instalar.",
"fpkg.openUpload_v2": "Abrir «Subir e instalar»",
"netdoctor.speed_cap.on.fix_v2": "Quita el límite en «Subir e instalar» si no lo necesitas.",
"payloads_fpkg_ppr_note_v2": "Instalar paquetes falsos también requiere a53_ppr_install_fast.elf, que no está en esta lista: no hay descarga publicada y se compila desde el código fuente en GitHub. «Subir e instalar» enumera todo lo que necesitan los paquetes falsos, en orden.",
"fs_extract_next_pkgs_v2": "Contiene {n} paquete(s): instálalos desde «Subir e instalar» o desde su fila aquí.",
"game_hub_no_addons_v2": "No hay paquetes DLC preparados para este título. Envía uno desde «Subir e instalar».",
"game_hub_open_install_v2": "Abrir «Subir e instalar»",
"bandwidth_cap_off_hint_v3": "Sin límite. Pon uno si las subidas saturan tu Wi-Fi/LAN y hacen ir lentos otros dispositivos. Se aplica a todas las subidas, desde «Subir e instalar», la cola y Archivos, a partir de la siguiente.",
"game_hub_no_updates_v2": "No hay paquetes de actualización preparados para este título. Envía uno desde «Subir e instalar».",
"pkglib.fpkgsupport.firmware": "Los paquetes falsos de PS5 (PS5 FPKG) aún no son compatibles con firmware posterior a 11.60: se instalan, pero el juego no arranca. Los paquetes falsos de PS4 funcionan bien.",
"upload_drop_here3": "Suelta o elige paquetes, juegos, imágenes de disco, archivos comprimidos o cualquier archivo",
"upload_pick_here_mobile3": "Elige paquetes, juegos, imágenes de disco, archivos comprimidos o cualquier archivo",
"upload_drop_kind_pkg": "Paquetes (.pkg, .fpkg): se instalan como juego, actualización o DLC, transmitidos desde aquí o subidos primero.",
"upload_drop_kind_game": "Carpetas de juego y volcados de juegos: se copian a la PS5; pueden ir a la pantalla de inicio.",
"upload_drop_kind_image": "Imágenes de disco (.exfat, .ffpkg, .ffpfs, .ffpfsc): se copian a la PS5; se pueden montar.",
"upload_drop_kind_archive": "Archivos comprimidos (.zip, .7z, .rar): se extraen en la PS5 o se envían tal cual; tú eliges.",
"upload_drop_kind_other": "Cualquier otro archivo o carpeta: se copia tal cual.",
"upload_other_ways": "O instala un paquete:",
"queue_stream_fail_hint": "«Transmitir e instalar» hace que la PS5 obtenga el paquete desde este ordenador. Si sigue fallando, permite ps5upload en el cortafuegos de este ordenador en la red local para que la PS5 pueda llegar a él, o usa «Reintentar subiéndolo», que primero copia el paquete a la PS5 y luego lo instala.",
"err_install_enoent_generic_v2": "El instalador de Sony no pudo abrir un archivo que necesitaba durante la instalación (error del kernel 0x80020002 = ENOENT). Si es un pkg de DLC, el juego base aún no está instalado — instala primero la base. Si no, puede que el paquete preparado se borrara entre la subida y la instalación; reintenta la instalación una vez. Si sigue fallando, instálalo con «Transmitir e instalar» en «Subir e instalar», que envía el paquete directamente desde este ordenador en lugar de copiarlo primero a la consola.",
"err_display_crashed": "La pantalla de la app tuvo un error durante esto (React #185) y dejó de seguir la transferencia, que puede haber terminado igualmente. Revisa la PS5 o pulsa Reintentar. Enviar ahora un informe de errores nos ayuda a arreglarlo.",
"upload_convert_first": "Convertir primero",
"batch_convert_first_hint": "Abrir los juegos, carpetas e imágenes marcados en el Taller, para convertirlos primero en paquetes, imágenes o carpetas",
"add_sources_pick_folders": "Elige una o más carpetas",
"add_sources_pick_files": "Elige uno o más archivos",
"workshop_add_hint": "Elige un juego para revisarlo aquí. Varios juegos, o una carpeta de juegos, van a la cola y se crean uno tras otro.",
"cq_title_v2": "⑤ Cola",
"cq_about": "Se crean uno tras otro en este ordenador, cada uno según cómo estaban ②, ③ y ④ al añadirlo. Añade más en ①, incluso mientras la cola avanza; cambia un juego en espera con su botón de opciones.",
