"add_sources_no_picker": "Esta versión no puede explorar este equipo: escribe una ruta que el motor pueda ver.",
"collection.empty_body_v2": "Se encuentran los paquetes, carpetas de juego, imágenes de juego y archivos comprimidos que contenga, agrupados por juego. No se cambia nada en la carpeta. Sirve una carpeta de este dispositivo, una unidad externa o una carpeta de un NAS o servidor (SMB, FTP, SFTP, WebDAV).",
