"queue_auto_start": "Iniciar la cola al añadir algo",
"queue_auto_start_tooltip": "Activado: «Instalar», «Subir ahora» y «Enviar» inician toda la cola de esta consola, en orden. Desactivado: solo añaden a la cola, y nada se ejecuta hasta que pulses «Iniciar cola».",
"queue_auto_start_hint": "Activado: «Instalar», «Subir ahora» y «Enviar» inician toda la cola de la consola, en orden, no solo lo que acabas de añadir. Desactivado: solo añaden a la cola, y nada se ejecuta hasta que pulses «Iniciar cola». Activado por defecto.",
"queue_start_rest_tooltip": "Solo se están ejecutando los elementos que iniciaste. Esto ejecuta también todo lo que espera, en el orden de la cola.",
