mcp_phone_title: "Configúralo en un ordenador",
mcp_phone_body: "El motor de esta app móvil es solo para la propia app. Para usar un agente o un script, ejecútalos en un ordenador con PS5Upload abierto o con el motor de Docker.",
mcp_other_computer_title: "Este motor está en otro ordenador",
mcp_other_computer_body: "Un agente en ese ordenador puede seguir estos pasos con su propia dirección 127.0.0.1. Un agente en cualquier otro sitio también necesita su dirección en el ajuste PS5UPLOAD_ALLOW_IP del motor.",
mcp_intro: "MCP permite que un agente de IA controle tu PS5 con herramientas que entiende: enviar archivos, instalar juegos, ver temperaturas y más. Añádelo una vez y luego solo pídeselo.",
mcp_address: "Dirección MCP",
mcp_agents_title: "Añádelo a tu agente",
mcp_check_again: "Comprobar de nuevo",
mcp_after_adding: "Inicia una sesión nueva en tu agente para cargarlo. Mantén PS5Upload abierto mientras el agente trabaja: el servidor MCP forma parte de su motor.",
mcp_update_title: "Mantenerlo al día",
mcp_update_app: "Cuando PS5Upload se actualiza, no hay nada que hacer aquí. Los agentes reciben sus herramientas del motor, así que las nuevas aparecen la próxima vez que inicies una sesión. Una sesión ya abierta conserva la lista antigua.",
mcp_update_address: "Si cambia la dirección del motor, la app te avisa al iniciarse y la tarjeta del agente muestra Actualizar. Un clic lo soluciona.",
mcp_update_by_hand: "La app no puede ver Gemini CLI, Cursor, Claude Desktop ni tus propios scripts. Si cambia la dirección de aquí, o alguno deja de conectar tras una actualización, vuelve a copiar su configuración desde Otros agentes y apps.",
mcp_update_version: "Este motor es la versión {version}. Para ver a qué está conectado un agente, pregúntale qué versión tiene el motor de PS5Upload.",
mcp_bridge_body: "Ejecuta el programa puente del motor en lugar de usar esta dirección. También funciona. Actualizar lo cambia a la dirección.",
mcp_stale_toast: "Un agente aún tiene la dirección antigua del motor, así que no puede conectarse. Actualízalo en MCP & API.",
