cb_users_title: "Qué partidas van a quién",
cb_users_hint: "Una PS5 restablecida tiene usuarios nuevos, aunque se llamen igual. Una partida solo puede ir a la partida guardada de ese usuario en el juego, así que inicia antes cada juego una vez con él y guarda.",
