cb_title: "Copia y restauración",
cb_desc: "Guarda en este ordenador lo que merece la pena y recupéralo tras un restablecimiento.",
cb_no_console: "Conéctate primero a una PS5.",
cb_step_restart: "Reinicia y entra otra vez en modo seguro",
cb_step_restart_body: "El modo seguro puede abrirse mostrando solo la última opción, Restablecer PS5 (reinstalar el software del sistema). Según algunos usuarios, elegir Reiniciar PS5 y entrar de nuevo en modo seguro devuelve las demás opciones. Prueba esto antes que nada.",
cb_step_repair: "Reparar almacenamiento de la consola",
cb_step_repair_body: "Comprueba la unidad y la repara. No borra nada, así que es la primera opción real que probar.",
cb_step_rebuild: "Borrar caché y reconstruir base de datos",
cb_step_rebuild_body: "Reconstruye la lista de contenido de la consola. Conserva tus juegos y partidas guardadas. En una consola con jailbreak, los juegos y apps registrados a mano puede que haya que registrarlos otra vez. Algunos dicen que con esto bastó, pero no lo hemos confirmado.",
cb_step_defaults: "Restaurar ajustes predeterminados",
cb_step_defaults_body: "Devuelve los ajustes a sus valores predeterminados y conserva tus juegos y partidas guardadas.",
cb_step_reset: "Restablecer PS5",
cb_step_reset_body: "Borra usuarios, juegos y partidas guardadas. No toca el software del sistema instalado, así que tu firmware no cambia y no necesitas una unidad USB. Si las opciones anteriores no ayudaron, usa esta.",
cb_step_reinstall: "Restablecer PS5 (reinstalar el software del sistema)",
cb_step_reinstall_body: "El último recurso: también elimina el software del sistema y necesita un archivo de reinstalación en una unidad USB. El sitio de Sony solo ofrece la versión más reciente, así que usar su archivo actualiza tu firmware y puede acabar con tu jailbreak.",
cb_usb_format: "Formatea la unidad como FAT32 o exFAT.",
cb_usb_folders: "Crea una carpeta llamada PS5 y, dentro, otra llamada UPDATE, en mayúsculas.",
cb_usb_file: "Guarda ahí el archivo como PS5UPDATE.PUP. Debe ser el archivo de reinstalación, que es mucho más grande que el de actualización.",
cb_usb_refused: "Si la PS5 sigue sin encontrar el archivo, revisa esos tres puntos y prueba con otra unidad: algunas no funcionan.",
cb_after_offline: "Configura la PS5 sin conectarla a internet y rechaza cualquier actualización del sistema que te ofrezca. Una actualización puede acabar con tu jailbreak.",
cb_after_user: "Vuelve a crear tus usuarios. En Cuentas están los pasos para darle a un usuario nuevo su antiguo ID de cuenta.",
cb_after_jailbreak: "Haz jailbreak de nuevo a la consola y envía el helper; luego abre esta pantalla y restaura tu copia.",
cb_enter_title: "Cómo entrar en modo seguro",
cb_enter_body: "Apaga la PS5. Mantén pulsado el botón de encendido hasta oír el segundo pitido, unos siete segundos. Conecta el mando con un cable USB y pulsa el botón PS.",
cb_steps_title: "Qué probar, en este orden",
cb_steps_hint: "Cada paso cuesta más que el anterior. Para en cuanto la PS5 arranque.",
