"pairing_closed_body_v4": "Esta PS5 pregunta antes de que se conecte un dispositivo nuevo, y ahora muestra este como pendiente. En un dispositivo que ya use esta PS5 (Conexión), o en la página de la propia PS5 (Configuración › Dispositivos), pulsa Permitir: esta app entrará sola. O pulsa Reenviar ayudante, que deja entrar a esta app.",
