"cw_tn_sign_out": "Cerrar sesión en Tailscale",
"cw_tn_sign_out_confirm": "¿Cerrar la sesión de Tailscale en esta PS5? Olvida su sesión: tendrás que volver a iniciarla, y puede recibir otra dirección. Para pararla un rato, desactívala.",
"cw_tn_sub": "Juega en esta PS5 desde cualquier lugar por tu red de Tailscale. Solo Remote Play y PS5Upload pueden llegar a ella por esta vía. También puedes configurarlo desde la app PS5Upload: Conexión › Tailscale para esta PS5.",
