"settings_tab_app": "App",
"settings_tab_ps5": "Esta PS5",
"settings_group_network": "Jugar juntos y Tailscale",
"tn_title_device": "Tailscale en este dispositivo",
"settings_ps5_none_title": "Aún no hay PS5",
"settings_ps5_none_body": "Añade tu PS5 en la pantalla Conexión y aquí verás sus propios ajustes.",
"settings_ps5_open_connection": "Abrir Conexión",
"settings_ps5_picker": "PS5",
"settings_ps5_picker_hint": "Estos ajustes son solo de esta PS5. Cada una de tus consolas tiene los suyos, y la siguen a tus otros dispositivos.",
"auto_bringup_hint_ps5": "Cuando el cargador de esta PS5 (elfldr, puerto 9021) está activo y el ayudante no se ejecuta, la app hace la puesta en marcha rápida por sí sola: la lista de arranque de esta PS5 si elegiste una, luego el ayudante y luego tu lista del cargador automático. Una vez cada vez que esta PS5 arranca; tras el modo reposo solo se vuelve a enviar el ayudante. Espera unos 90 segundos tras aparecer el cargador, para que el cargador automático de la consola termine primero. Desactivado por defecto.",
"bringup_playlist_label_ps5": "Lista de arranque para esta PS5 (kernel R/W, SMP)",
"bringup_playlist_hint_ps5": "Se ejecuta antes del ayudante durante la puesta en marcha rápida. Los payloads dependen del firmware, así que cada PS5 tiene la suya. Crea listas en Payloads.",
"upload_auto_redeploy_on_wake_hint_ps5": "Cuando el ayudante de esta PS5 se desconecta (modo reposo, cambio de Wi-Fi o fallo de un payload), seguir intentando enviarlo de nuevo en segundo plano, para que el ayudante, el umbral del ventilador de esta PS5 y el puerto de subida vuelvan solos en cuanto se pueda llegar a ella. Activado por defecto.",
"keep_ps5_awake_mode_hint_ps5": "Reinicia el temporizador de reposo automático de esta PS5 para que no entre en modo reposo. «Durante subidas e instalaciones» protege las subidas largas (una causa frecuente de fallos; predeterminado). «Siempre mientras esté conectada» mantiene esta PS5 fuera del modo reposo mientras su ayudante se ejecuta y la app está abierta. Poner tú la PS5 en reposo sigue funcionando en cualquier modo.",
"upload_rest_after_hint_ps5": "Cuando termine la cola de subidas de esta PS5, pedirle que entre en modo reposo, útil para una cola nocturna. Solo si al menos una subida terminó bien (no tras Detener ni si todo falló). Desactivado por defecto. Algunos firmwares rechazan el modo reposo; verás un aviso si esta PS5 lo hace.",
"upload_wake_for_uploads_hint_ps5": "Cuando una subida espera a esta PS5 en modo reposo, enviarle una señal para encenderla y seguir en cuanto vuelva su ayudante. Requiere configurar el encendido de esta PS5 en la pantalla Conexión. Activado por defecto.",
"install_path_fallback_hint_ps5": "Un último recurso para un paquete que ya está en esta PS5, cuando lo rechaza desde su propio almacenamiento y tampoco puede traerlo de este equipo. Solo se usa para un juego base que no está instalado, así que no puede quitar nada. Sin probar del todo: funcionó en el firmware 11.20 y se rechaza en 13.60, por eso se ajusta para cada PS5. Si lo pruebas, cuéntanos si funcionó.",
"settings_group_ps5_elsewhere": "Más para esta PS5",
"settings_card_ps5_elsewhere": "En otras pantallas",
"settings_ps5_elsewhere_hint": "Estos se guardan en la propia PS5 y se ajustan donde se usan. Abrir uno selecciona esta PS5.",
